graph-absent-with-annotations.body:
const stylesheet = create(StylesheetSchema, {
  annotations: { note: create(AnnotationEntrySchema, {}) },
});
const diagram = create(DiagramSchema, {});
const theme = create(ThemeSchema, { defaultAnnotationComponent: 'glyph' });
const result = seedComponentBindings(diagram, stylesheet, theme);
expect(result.annotations.note.component).toBe('glyph');

stylesheet-not-mutated.body:
const stylesheet = create(StylesheetSchema, {});
const diagram = create(DiagramSchema, {});
const theme = create(ThemeSchema, {});
const result = seedComponentBindings(diagram, stylesheet, theme);
expect(result).not.toBe(stylesheet);
expect(stylesheet).toEqual(create(StylesheetSchema, {}));

theme-absent.body:
const stylesheet = create(StylesheetSchema, {});
const diagram = create(DiagramSchema, {});
expect(seedComponentBindings(diagram, stylesheet, undefined)).toBe(stylesheet);
